import { getStore } from "@netlify/blobs";

// ── check-code: validates and claims entry codes ────────────────────
//
// Handles two types of codes:
//   1. Legacy beta codes (HEALFREE, BETAMARK, etc.) — kept for existing users
//   2. Per-buyer unique codes (HM-XXXX-XXXX) — generated by stripe-webhook.mjs
//
// Actions:
//   claim   — mark code as used; reject if already claimed by someone else
//   resend  — look up buyer's code by email, fire Swipe One event to resend it
//   (none)  — check-only, return whether code is valid/used

export default async (req, context) => {
  const codeStore = getStore("used-codes");
  const buyerStore = getStore("buyer-codes");

  try {
    const body = await req.json();
    const action = body.action;
    const normalizedCode = (body.code || "").trim().toUpperCase();
    const email = (body.email || "").trim().toLowerCase();

    // ── RESEND: buyer enters their email to get their code again ──
    if (action === "resend") {
      if (!email) {
        return json({ success: false, reason: "missing_email" }, 400);
      }
      const buyerRecord = await buyerStore.get(email, { type: "json" }).catch(() => null);
      if (!buyerRecord || !buyerRecord.code) {
        return json({
          success: false,
          reason: "not_found",
          message: "We couldn't find a purchase for that email address. Please check your email or contact support@healingmomentumapp.com."
        });
      }

      // Fire a Swipe One event to re-trigger the welcome email automation
      const appUrl = "https://healingmomentumapp.com?welcome=1&code=" + buyerRecord.code;
      await fireSwipeOneEvent({ email, code: buyerRecord.code, appUrl, eventType: "code_resend_requested" });

      return json({ success: true, message: "Code sent! Check your email." });
    }

    // ── VALIDATE / CLAIM ──────────────────────────────────────────
    if (!normalizedCode) {
      return json({ valid: false, reason: "missing_code" }, 400);
    }

    // Legacy beta codes (kept so existing users always work)
    const LEGACY_CODES = ["FOUNDER50", "FOUNDER2026", "HEALFREE", "BETAMARK", "DRKTRIAL"];
    const isLegacy = LEGACY_CODES.includes(normalizedCode);

    // Per-buyer codes match HM-XXXX-XXXX pattern
    const isPerBuyer = /^HM-[A-Z0-9]{4}-[A-Z0-9]{4}$/.test(normalizedCode);

    if (!isLegacy && !isPerBuyer) {
      return json({ valid: false, reason: "unknown_code" });
    }

    const existing = await codeStore.get(normalizedCode, { type: "json" }).catch(() => null);

    if (action === "claim") {
      if (existing && existing.used) {
        // Per-buyer codes: if the same email is reclaiming, let them back in
        // (handles reinstalling on a new device with the same code)
        if (isPerBuyer && email && existing.email === email) {
          return json({ valid: true, claimed: true, returning: true });
        }
        return json({
          valid: false,
          reason: "already_used",
          message: "This access code has already been used to create an account. If this is your code, use the Returning User option or tap Resend my code below."
        });
      }

      // Mark as claimed
      const claimData = {
        used: true,
        claimedAt: new Date().toISOString(),
        ...(isPerBuyer && existing ? {
          email: existing.email,
          name: existing.name,
          customerId: existing.customerId,
          issuedAt: existing.issuedAt,
          stripeSessionId: existing.stripeSessionId
        } : {})
      };
      await codeStore.setJSON(normalizedCode, claimData);

      return json({ valid: true, claimed: true });
    }

    // Check-only (no action specified)
    const isUsed = existing && existing.used;
    return json({ valid: true, used: !!isUsed });

  } catch (err) {
    console.error("check-code error:", err);
    return json({ valid: false, reason: "server_error", error: String(err) }, 500);
  }
};

// ── Swipe One: fire an event on a contact to trigger an automation ──
async function fireSwipeOneEvent({ email, code, appUrl, eventType }) {
  const apiKey = process.env.SWIPE_ONE_API_KEY;
  const writeKey = process.env.SWIPE_ONE_WRITE_KEY;
  const workspaceId = process.env.SWIPE_ONE_WORKSPACE_ID;
  const baseUrl = "https://api.swipeone.com/api";

  if (!apiKey || !workspaceId) {
    console.warn("Swipe One not configured — skipping resend event");
    return false;
  }

  try {
    // Look up the contact by email first
    const searchRes = await fetch(baseUrl + "/workspaces/" + workspaceId + "/contacts?email=" + encodeURIComponent(email), {
      headers: { "x-api-key": apiKey }
    });
    if (!searchRes.ok) return false;
    const searchData = await searchRes.json();
    const contactId = searchData?.data?.[0]?._id || searchData?.data?.[0]?.id;
    if (!contactId) return false;

    // Fire the resend event
    const evKey = writeKey || apiKey;
    const evRes = await fetch(baseUrl + "/workspaces/" + workspaceId + "/events", {
      method: "POST",
      headers: { "x-api-key": evKey, "Content-Type": "application/json" },
      body: JSON.stringify({
        contact: { id: contactId },
        type: eventType || "code_resend_requested",
        properties: { entryCode: code, appUrl }
      })
    });
    return evRes.ok;
  } catch (err) {
    console.error("Swipe One event failed:", err);
    return false;
  }
}

function json(data, status) {
  return new Response(JSON.stringify(data), {
    status: status || 200,
    headers: { "Content-Type": "application/json" }
  });
}

export const config = {
  path: "/api/check-code"
};
